    if ($_GET['ajax'] !== 'search_categories') beta_tg_fail('Unknown action.');
    if (mb_strlen((string) ($_GET['q'] ?? '')) > 200) beta_tg_fail('Search is too long.');
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $bA = (string) ($_POST['tracker_action'] ?? '');
    $bP = fn($k) => (string) ($_POST[$k] ?? '');
    if (!in_array($bA, ['add_game', 'update_status', 'update_100', 'set_time', 'delete_game', 'add_denylist', 'remove_denylist', 'sessions'], true)) beta_tg_fail('Unknown action.');
    if (in_array($bA, ['update_status', 'update_100', 'set_time', 'delete_game', 'remove_denylist', 'sessions'], true) && !preg_match('/^[1-9]\d{0,9}$/', $bP('id'))) beta_tg_fail('Unknown game.');
    if ($bA === 'add_game' || $bA === 'add_denylist') {
        $bT = trim($bP('title'));
        if ($bT === '' || mb_strlen($bT) > 255) beta_tg_fail('Game titles must be 1 to 255 characters.');
        if (preg_match('/[\x00-\x1F\x7F]/u', $bT)) beta_tg_fail('Game titles cannot contain line breaks or control characters.');
        if ($bP('twitch_game_id') !== '' && !preg_match('/^\d{1,32}$/', $bP('twitch_game_id'))) beta_tg_fail('Unknown Twitch category.');
        // Box art only from Twitch's CDN; anything else is rebuilt from the category id.
        if (isset($_POST['box_art_url']) && !preg_match('#^https://static-cdn\.jtvnw\.net/[A-Za-z0-9/_.%{}\-]+$#', $bP('box_art_url'))) unset($_POST['box_art_url']);
    }
    if ($bA === 'update_status' && !in_array($bP('status'), ['playing', 'on_hold', 'finished', 'dropped'], true)) beta_tg_fail('Choose a status.');
    if ($bA === 'update_100' && !in_array($bP('completion_100'), ['', '1'], true)) beta_tg_fail('Invalid on/off value.');
    if ($bA === 'set_time') {
        if (!preg_match('/^\d{1,5}$/', $bP('hours')) || (int) $bP('hours') > 99999) beta_tg_fail('Hours must be a whole number from 0 to 99999.');
        if (!preg_match('/^\d{1,2}$/', $bP('minutes')) || (int) $bP('minutes') > 59) beta_tg_fail('Minutes must be a whole number from 0 to 59.');
    }
}
$helixToken = (string)($_SESSION['access_token'] ?? '');
